begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id) values ('50000000-0000-0000-0000-000000000001'), ('50000000-0000-0000-0000-000000000002');
select is((select count(*)::int from jobpilot_private.owner_registration), 0, 'requires local unbootstrapped database');
insert into jobpilot_private.owner_registration(user_id) values ('50000000-0000-0000-0000-000000000001');
select ok(relrowsecurity, relname || ' has RLS') from pg_class where oid in ('public.discovery_automation'::regclass, 'public.automation_runs'::regclass);
select ok(not has_table_privilege('anon', 'public.' || t, 'SELECT'), 'anonymous cannot read ' || t) from unnest(array['discovery_automation','automation_runs']) t;
select ok(not has_table_privilege('authenticated', 'public.' || t, 'UPDATE'), 'browser cannot mutate ' || t) from unnest(array['discovery_automation','automation_runs']) t;
select ok(not has_function_privilege('authenticated', p.oid, 'EXECUTE') and not has_function_privilege('anon', p.oid, 'EXECUTE'), 'browser cannot execute ' || p.proname)
from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any(array['set_discovery_automation','claim_discovery_automation','scheduled_discovery_sources','discovery_automation_active','start_scheduled_import','store_import_candidate','finish_discovery_automation']);
set local role service_role;
select is((public.claim_discovery_automation()).id, null::uuid, 'no schedule defaults OFF');
select public.set_discovery_automation('50000000-0000-0000-0000-000000000001', false);
select is((select enabled from public.discovery_automation), false, 'explicit off persists');
select public.set_discovery_automation('50000000-0000-0000-0000-000000000001', true);
select is((public.claim_discovery_automation()).id, null::uuid, 'cannot run before next hourly slot');
insert into public.job_sources(id,owner_id,kind,source_key,name,enabled) values
 ('51000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','greenhouse','confirmed','Confirmed',true),
 ('51000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000001','greenhouse','disabled','Disabled',false),
 ('51000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001','manual','manual','Manual',true);
update public.discovery_automation set next_run_at = now() - interval '1 minute';
select ok((public.claim_discovery_automation()).id is not null, 'due enabled schedule can claim');
select is((public.claim_discovery_automation()).id, null::uuid, 'duplicate tick skipped');
update public.discovery_automation set next_run_at = now() - interval '1 minute';
select is((public.claim_discovery_automation()).id, null::uuid, 'running lease blocks overlapping tick even when due');
select is((select count(*)::int from public.scheduled_discovery_sources((select id from public.automation_runs))), 1, 'only explicitly enabled provider sources selected');
select public.start_scheduled_import((select id from public.automation_runs), '51000000-0000-0000-0000-000000000001');
select throws_ok($$select public.start_job_import('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001')$$, '23505', null, 'manual and scheduled imports share overlap protection');
select throws_ok($$select public.start_scheduled_import((select id from public.automation_runs), '51000000-0000-0000-0000-000000000002')$$, 'P0001', 'Source unavailable', 'disabled source rejected atomically');
select is(public.store_import_candidate('50000000-0000-0000-0000-000000000001',(select id from public.import_runs),'42','{"title":"Fixture","description":"Test","canonical_url":"https://example.invalid/42","requirements":[],"uncertainty":[]}','{}'), true, 'scheduled worker stores a job');
select is(public.store_import_candidate('50000000-0000-0000-0000-000000000001',(select id from public.import_runs),'42','{}','{}'), false, 'retry deduplicates');
update public.job_sources set enabled = false where source_key = 'confirmed';
select throws_ok($$select public.store_import_candidate('50000000-0000-0000-0000-000000000001',(select id from public.import_runs),'43','{}','{}')$$, 'P0001', 'Source unavailable', 'disable during run fences writes');
update public.job_sources set enabled = true where source_key = 'confirmed';
select public.set_discovery_automation('50000000-0000-0000-0000-000000000001', false);
select is((select status from public.automation_runs), 'paused', 'pause cancels active schedule');
select throws_ok($$select public.store_import_candidate('50000000-0000-0000-0000-000000000001',(select id from public.import_runs),'43','{}','{}')$$, 'P0001', 'Schedule paused or expired', 'pause fences delayed writes');
select public.finish_job_import('50000000-0000-0000-0000-000000000001',(select id from public.import_runs),null,'bad-stale-cursor',1,0);
select is((select cursor from public.job_sources where source_key = 'confirmed'), null::text, 'late finish cannot advance paused cursor');
select is((select count(*)::int from public.imported_jobs), 1, 'pause preserves imported jobs');
select is((select imported_count from public.import_runs), 1, 'pause retains committed server-side import count');
select public.set_discovery_automation('50000000-0000-0000-0000-000000000001', true);
select throws_ok($$select public.store_import_candidate('50000000-0000-0000-0000-000000000001',(select id from public.import_runs),'43','{}','{}')$$, 'P0001', 'Schedule paused or expired', 'resume never revives old worker');
update public.discovery_automation set next_run_at = now() - interval '1 minute';
select ok((public.claim_discovery_automation()).id is not null, 'resume permits a new run');
select public.start_scheduled_import((select id from public.automation_runs where status = 'running'), '51000000-0000-0000-0000-000000000001');
insert into public.job_sources(owner_id,kind,source_key,name) select '50000000-0000-0000-0000-000000000001','greenhouse','new-' || n,'New board ' || n from generate_series(1,4) n;
select is((select count(*)::int from public.scheduled_discovery_sources((select id from public.automation_runs where status = 'running'))), 3, 'scheduled source batch limited to three');
select is((select count(*)::int from public.scheduled_discovery_sources((select id from public.automation_runs where status = 'running')) where source_key = 'confirmed'), 0, 'unattempted boards precede recently attempted source');
update public.automation_runs set lease_until = now() - interval '1 second' where status = 'running';
select throws_ok($$select public.store_import_candidate('50000000-0000-0000-0000-000000000001',(select id from public.import_runs where status = 'running'),'43','{}','{}')$$, 'P0001', 'Schedule paused or expired', 'expired lease fences writes');
select public.claim_discovery_automation();
select is((select count(*)::int from public.automation_runs where error_code = 'interrupted'), 1, 'abandoned lease recovered as failure');
select is((select count(*)::int from public.import_runs where status = 'running'), 0, 'abandoned source lock recovered');
insert into public.gmail_connections(owner_id,expected_email) values('50000000-0000-0000-0000-000000000001','first@example.invalid');
select public.set_gmail_label('50000000-0000-0000-0000-000000000001','Label_fixture','Fixture label');
select is((select confirmed_email from public.job_sources where kind = 'gmail'), 'first@example.invalid', 'label confirmation binds current mailbox');
update public.gmail_connections set expected_email = 'first@example.invalid';
select ok((select enabled and confirmed_email is not null from public.job_sources where kind = 'gmail'), 'same mailbox reconnect preserves label confirmation');
update public.gmail_connections set expected_email = 'second@example.invalid';
select ok((select not enabled and confirmed_email is null from public.job_sources where kind = 'gmail'), 'mailbox switch invalidates confirmation and pauses label');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.discovery_automation), 1, 'owner reads setting');
select is((select count(*)::int from public.automation_runs), 2, 'owner reads run history');
select is((select count(*)::int from public.latest_scheduled_imports), 1, 'owner reads latest scheduled result per source');
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000002',true);
select is((select count(*)::int from public.discovery_automation), 0, 'non-owner cannot read setting');
select is((select count(*)::int from public.automation_runs), 0, 'non-owner cannot read runs');
select is((select count(*)::int from public.latest_scheduled_imports), 0, 'latest-result view respects underlying owner RLS');
reset role;
select * from finish();
rollback;
